begin
    import Pkg, TOML
    notebook_root = get(ENV, "PERFCHECKER_DATASTRUCTURES_NOTEBOOK_ROOT", joinpath(homedir(), ".julia", "dev", "PerfCheckerNotebookExamples", "datastructures"))
    controller_project = joinpath(notebook_root, "controller")
    Pkg.activate(controller_project; io=devnull)
    package_specs = [Pkg.PackageSpec(name="PerfChecker",version="1.1.0"),Pkg.PackageSpec(name="PerfCheckerMakie",version="1.0.1"),Pkg.PackageSpec(name="PerfCheckerPluto",version="1.0.1"),Pkg.PackageSpec(name="PlutoUI",version="0.7.83"),Pkg.PackageSpec(name="BenchmarkTools",version="1.7.0"),Pkg.PackageSpec(name="Chairmarks",version="1.3.1"),Pkg.PackageSpec(name="WGLMakie",version="0.13.15"),Pkg.PackageSpec(name="JSON",version="1"),Pkg.PackageSpec(name="UnicodePlots",version="3"),Pkg.PackageSpec(name="DataStructures",version="0.19.6")]
    declared = isfile(joinpath(controller_project,"Project.toml")) ? get(TOML.parsefile(joinpath(controller_project,"Project.toml")),"deps",Dict()) : Dict()
    any(spec -> !haskey(declared,spec.name),package_specs) && Pkg.add(package_specs)
    using PerfChecker, PerfCheckerMakie, PerfCheckerPluto, PlutoUI, BenchmarkTools, Chairmarks, WGLMakie, JSON, UnicodePlots
    @assert pkgversion(PerfChecker)==v"1.1.0"
    @assert pkgversion(PerfCheckerMakie)==v"1.0.1"
    @assert pkgversion(PerfCheckerPluto)==v"1.0.1"
    WGLMakie.activate!()
    runtime_sources = Dict("workloads/counter_64.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"counter\", \"n\" => 64))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/IntDisjointSet_connectivity.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"IntDisjointSet\", \"connectivity\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/BinaryMinMaxHeap_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMinMaxHeap\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/RobinDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"RobinDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/CircularBuffer_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"CircularBuffer\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/LinkedList_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"LinkedList\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedRobinDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedRobinDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/PriorityQueue_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"PriorityQueue\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "workloads/counter_32768.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"counter\", \"n\" => 32768))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/Deque_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Deque\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/DefaultOrderedDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"DefaultOrderedDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/RBTree_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"RBTree\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SparseIntSet_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SparseIntSet\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SparseIntSet_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SparseIntSet\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/LinkedList_traverse.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"LinkedList\", \"traverse\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Accumulator_traverse.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Accumulator\", \"traverse\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/RBTree_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"RBTree\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedSet_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedSet\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "src/PerfCheckerKitchenSink.jl" => "module PerfCheckerKitchenSink\nusing DataStructures\nusing Random\n\nexport events, drain_heap, drain_vector, count_events, recent_events, event_case\n\n# Select the public constructor once, outside measurement. Older releases used\n# a lowercase function for the same min-heap operation.\nconst make_minheap = isdefined(DataStructures, :BinaryMinHeap) ?\n                     DataStructures.BinaryMinHeap : DataStructures.binary_minheap\n\n\"Generate immutable (priority, unique id, category) events from a fixed seed.\"\nfunction events(n::Integer = 2048; seed::Integer = 42)\n    n >= 0 || throw(ArgumentError(\"event count must be nonnegative\"))\n    rng = Random.Xoshiro(seed)\n    return [(rand(rng, 1:max(n, 1)), i, rand(rng, 1:16)) for i in 1:n]\nend\n\n\"Build and drain a binary heap; input generation is outside this operation.\"\nfunction drain_heap(input)\n    queue = make_minheap(input)\n    output = similar(input, 0)\n    sizehint!(output, length(input))\n    while !isempty(queue)\n        push!(output, pop!(queue))\n    end\n    return output\nend\n\n\"A deliberately simple sorted-vector queue with the same output as drain_heap.\"\nfunction drain_vector(input)\n    queue = sort(input)\n    output = similar(input, 0)\n    sizehint!(output, length(input))\n    while !isempty(queue)\n        push!(output, popfirst!(queue))\n    end\n    return output\nend\n\n\"Count categories using an Accumulator and return an ordinary dictionary.\"\ncount_events(input) = Dict(counter(event[3] for event in input))\n\n\"Retain the last 64 events in arrival order using a circular buffer.\"\nfunction recent_events(input)\n    buffer = CircularBuffer{eltype(input)}(64)\n    append!(buffer, input)\n    return collect(buffer)\nend\n\n\"One oracle-bearing lifecycle shared by correctness tests, scenarios and suite workers.\"\nfunction event_case(parameters)\n    n = Int(get(parameters, \"n\", 2048))\n    input = events(n; seed = Int(get(parameters, \"seed\", 42)))\n    kind = String(get(parameters, \"kind\", \"heap\"))\n    operation = kind == \"heap\" ? drain_heap :\n                kind == \"vector\" ? drain_vector :\n                kind == \"counter\" ? count_events :\n                kind == \"buffer\" ? recent_events :\n                throw(ArgumentError(\"Choose heap, vector, counter or buffer\"))\n    expected = if kind in (\"heap\", \"vector\")\n        sort(input)\n    elseif kind == \"counter\"\n        Dict(category => count(e -> e[3] == category, input)\n        for category in unique(e[3] for e in input))\n    else\n        input[max(1, length(input) - 63):end]\n    end\n    return (prepare = () -> copy(input), operation = operation,\n        verify = (state, result) -> result == expected && state == input)\nend\nend\n", "containers/AVLTree_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"AVLTree\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Queue_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Queue\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/LittleDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"LittleDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/BinaryMaxHeap_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMaxHeap\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/MutableLinkedList_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"MutableLinkedList\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "workloads/buffer_64.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"buffer\", \"n\" => 64))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/SortedMultiDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SortedMultiDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SwissDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SwissDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/BinaryMinMaxHeap_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMinMaxHeap\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SortedSet_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SortedSet\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/AVLTree_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"AVLTree\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/IntDisjointSet_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"IntDisjointSet\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/CircularDeque_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"CircularDeque\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SwissDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SwissDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "src/containers.jl" => "\"\"\"\nIndependent container workloads for the DataStructures 0.19 release series.\n\nConstruction and use are different cases: lookup/drain samples receive a freshly\nbuilt container in `prepare`, outside the timed region. All inputs are fixed and\nall answers are compared with Base arrays/dictionaries, outside measurement.\n\"\"\"\nmodule ContainerCases\nusing DataStructures, Random\n\nconst FAMILIES = [\"Deque\", \"Queue\", \"Stack\", \"CircularDeque\", \"CircularBuffer\",\n    \"LinkedList\", \"MutableLinkedList\", \"BinaryMinHeap\", \"BinaryMaxHeap\",\n    \"MutableBinaryMinHeap\", \"MutableBinaryMaxHeap\", \"BinaryMinMaxHeap\",\n    \"PriorityQueue\", \"OrderedDict\", \"LittleDict\", \"DefaultDict\", \"DefaultOrderedDict\",\n    \"RobinDict\", \"OrderedRobinDict\", \"SwissDict\", \"SortedDict\", \"SortedMultiDict\",\n    \"MultiDict\", \"OrderedSet\", \"SortedSet\", \"SparseIntSet\", \"Accumulator\", \"Trie\",\n    \"IntDisjointSet\", \"DisjointSet\", \"FenwickTree\", \"DiBitVector\", \"AVLTree\", \"RBTree\", \"SplayTree\"]\n\nconst DICTS = [\"OrderedDict\", \"LittleDict\", \"DefaultDict\", \"DefaultOrderedDict\",\n    \"RobinDict\", \"OrderedRobinDict\", \"SwissDict\", \"SortedDict\"]\nconst SETS = [\"OrderedSet\", \"SortedSet\", \"SparseIntSet\"]\nconst TREES = [\"AVLTree\", \"RBTree\", \"SplayTree\"]\nconst HEAPS = [\"BinaryMinHeap\", \"BinaryMaxHeap\", \"MutableBinaryMinHeap\",\n    \"MutableBinaryMaxHeap\", \"BinaryMinMaxHeap\"]\n\n\"Construct a container by inserting a fixed permutation of unique integer keys.\"\nfunction construct(family, input)\n    n = length(input)\n    T = getfield(DataStructures, Symbol(family))\n    if family in DICTS\n        c = family in (\"DefaultDict\", \"DefaultOrderedDict\") ? T{Int, Int}(0) : T{Int, Int}()\n        for k in input\n            c[k] = 3k\n        end\n    elseif family in SETS || family in TREES\n        c = family == \"SparseIntSet\" ? T() : T{Int}()\n        for k in input\n            push!(c, k)\n        end\n    elseif family == \"Accumulator\"\n        c = counter(mod(k, 16) for k in input)\n    elseif family == \"Trie\"\n        c = Trie{Char, Int}()\n        for k in input\n            c[string(k)] = 3k\n        end\n    elseif family in (\"IntDisjointSet\", \"DisjointSet\")\n        c = family == \"IntDisjointSet\" ? IntDisjointSet(n) : DisjointSet(collect(1:n))\n        for k in 2:2:n\n            union!(c, k - 1, k)\n        end\n    elseif family == \"FenwickTree\"\n        c = FenwickTree(input)\n    elseif family == \"DiBitVector\"\n        c = DiBitVector(n)\n        for k in eachindex(input)\n            c[k] = mod(input[k], 4)\n        end\n    elseif family == \"LinkedList\"\n        c = nil(Int)\n        for k in reverse(input)\n            c = cons(k, c)\n        end\n    elseif family == \"MultiDict\"\n        c = MultiDict{Int, Int}()\n        for k in input\n            insert!(c, mod(k, 16), k)\n        end\n    elseif family == \"SortedMultiDict\"\n        c = SortedMultiDict{Int, Int}()\n        for k in input\n            push!(c, k => 3k)\n        end\n    elseif family == \"PriorityQueue\"\n        c = PriorityQueue{Int, Int}()\n        for k in input\n            c[k] = k\n        end\n    else\n        c = family in (\"CircularDeque\", \"CircularBuffer\") ? T{Int}(max(n, 1)) : T{Int}()\n        for k in input\n            push!(c, k)\n        end\n    end\n    return c\nend\n\n\"An untimed representation used to check construction against an independent answer.\"\nfunction canonical(family, c, input)\n    n = length(input)\n    if family in DICTS || family == \"SortedMultiDict\"\n        return sort!(collect(c); by = first)\n    elseif family in SETS\n        return sort!(collect(c))\n    elseif family in TREES\n        return [haskey(c, k) for k in 1:n]\n    elseif family == \"Trie\"\n        return [c[string(k)] for k in 1:n]\n    elseif family == \"Accumulator\"\n        return Dict(c)\n    elseif family == \"MultiDict\"\n        return Dict(k => sort(v) for (k, v) in c)\n    elseif family in (\"DisjointSet\", \"IntDisjointSet\")\n        return (num_groups(c), [in_same_set(c, k - 1, k) for k in 2:2:n])\n    elseif family == \"FenwickTree\"\n        return [prefixsum(c, k) for k in 1:n]\n    elseif family == \"PriorityQueue\"\n        return sort!(collect(c); by = first)\n    elseif family in HEAPS\n        return sort!([pop!(c) for _ in 1:n])\n    else\n        return collect(c)\n    end\nend\n\nfunction expected_construction(family, input)\n    n = length(input)\n    family in DICTS || family in (\"SortedMultiDict\", \"PriorityQueue\") ?\n    [k => (family == \"PriorityQueue\" ? k : 3k) for k in 1:n] :\n    family in SETS ? collect(1:n) :\n    family in TREES ? fill(true, n) :\n    family == \"Trie\" ? 3 .* collect(1:n) :\n    family == \"Accumulator\" ?\n    Dict(k => count(x -> mod(x, 16) == k, input) for k in unique(mod.(input, 16))) :\n    family == \"MultiDict\" ?\n    Dict(k => sort(filter(x -> mod(x, 16) == k, input)) for k in unique(mod.(input, 16))) :\n    family in (\"DisjointSet\", \"IntDisjointSet\") ? (n - fld(n, 2), fill(true, fld(n, 2))) :\n    family == \"FenwickTree\" ? cumsum(input) :\n    family == \"DiBitVector\" ? mod.(input, 4) :\n    family in HEAPS ? sort(input) :\n    family == \"Stack\" ? reverse(input) : copy(input)\nend\n\n\"The second operation isolates access, draining, traversal or prefix queries.\"\nfunction use_container(family, c, input)\n    if family in DICTS\n        return [c[k] for k in input]\n    elseif family in TREES\n        return [haskey(c, k) for k in input]\n    elseif family in SETS\n        return [k in c for k in input]\n    elseif family == \"Trie\"\n        return [c[string(k)] for k in input]\n    elseif family in (\"Deque\", \"Queue\", \"CircularDeque\", \"CircularBuffer\",\n        \"MutableLinkedList\", \"PriorityQueue\")\n        return [popfirst!(c) for _ in input]\n    elseif family in HEAPS || family == \"Stack\"\n        return [pop!(c) for _ in input]\n    else\n        return canonical(family, c, input)\n    end\nend\n\nfunction operation_name(family)\n    family in DICTS || family in SETS || family in TREES || family == \"Trie\" ? \"lookup\" :\n    family in HEAPS || family in (\"Deque\", \"Queue\", \"Stack\", \"CircularDeque\",\n        \"CircularBuffer\", \"MutableLinkedList\", \"PriorityQueue\") ? \"drain\" :\n    family == \"FenwickTree\" ? \"prefixsum\" :\n    family in (\"DisjointSet\", \"IntDisjointSet\") ? \"connectivity\" : \"traverse\"\nend\n\n\"Return an oracle-bearing case; no measurement or package installation happens here.\"\nfunction container_case(family::AbstractString, operation::AbstractString = \"build\";\n        n::Int = 512, seed::Int = 42)\n    family in FAMILIES || throw(ArgumentError(\"Unknown container: \$family\"))\n    n >= 0 || throw(ArgumentError(\"n must be nonnegative\"))\n    input = randperm(Random.Xoshiro(seed), n)\n    expected = expected_construction(family, input)\n    if operation == \"build\"\n        return (prepare = () -> copy(input), operation = x -> construct(family, x),\n            verify = (state, result) -> state == input &&\n                canonical(family, result, input) == expected)\n    end\n    operation == operation_name(family) ||\n        throw(ArgumentError(\"Invalid operation for \$family\"))\n    answer = if family in DICTS || family == \"Trie\"\n        3 .* input\n    elseif family in SETS || family in TREES\n        fill(true, n)\n    elseif family == \"PriorityQueue\"\n        [k => k for k in 1:n]\n    elseif family in HEAPS\n        sort(input; rev = family in (\"BinaryMaxHeap\", \"MutableBinaryMaxHeap\"))\n    else\n        expected\n    end\n    return (prepare = () -> construct(family, input),\n        operation = c -> use_container(family, c, input),\n        verify = (_, result) -> result == answer)\nend\nend\n", "workloads/vector_32768.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"vector\", \"n\" => 32768))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/Stack_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Stack\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/MutableBinaryMaxHeap_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"MutableBinaryMaxHeap\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/CircularBuffer_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"CircularBuffer\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/LittleDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"LittleDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Stack_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Stack\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/BinaryMinHeap_drain.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMinHeap\", \"drain\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/DiBitVector_traverse.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\ncons