e.verify(state, result)\n", "containers/SplayTree_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SplayTree\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedSet_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedSet\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/CircularDeque_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"CircularDeque\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/DiBitVector_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"DiBitVector\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/SortedDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SortedDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/BinaryMaxHeap_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMaxHeap\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers-suite.jl" => "using PerfChecker\ninclude(joinpath(@__DIR__, \"src/containers.jl\"))\nconst CONTAINER_VERSIONS = [VersionNumber(0, 19, patch) for patch in 0:6]\n\n\"Seventy independent construction/access cases across every DataStructures 0.19 patch.\"\nfunction build_container_suite(; backends = (:benchmark,))\n    features = FeatureSpec[]\n    for family in ContainerCases.FAMILIES,\n        operation in (\"build\", ContainerCases.operation_name(family)), backend in backends\n\n        id = family * \"_\" * operation\n        push!(features,\n            FeatureSpec(Symbol(id, \"_\", backend);\n                workload = Symbol(id), backend, oracle = OracleSpec(), state_policy = :fresh,\n                entrypoint = joinpath(@__DIR__, \"containers\", id * \".jl\"),\n                comparison_key = \"containers/\$(family)/\$(operation)/512/seed42/v1\",\n                options = Dict(\n                    :samples => 30, :evals => 1, :seconds => 0.25, :threads => 1)))\n    end\n    SoftwareSuite(:container_catalogue,\n        [PackageSuite(\"DataStructures\";\n            versions = CONTAINER_VERSIONS, include_dev = false,\n            worker_environment = joinpath(@__DIR__, \"workers\"), features)];\n        description = \"Independent construction and use of 35 containers; all 0.19 patches\")\nend\n", "containers/BinaryMinHeap_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"BinaryMinHeap\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/MultiDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"MultiDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "workloads/vector_64.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"vector\", \"n\" => 64))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/MutableBinaryMinHeap_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"MutableBinaryMinHeap\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/PriorityQueue_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"PriorityQueue\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/OrderedRobinDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"OrderedRobinDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Accumulator_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Accumulator\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "suite.jl" => "using PerfChecker\n\nconst KITCHEN_VERSIONS = [v\"0.11.0\", v\"0.12.0\", v\"0.13.0\", v\"0.14.0\", v\"0.15.0\",\n    v\"0.16.1\", v\"0.17.0\", v\"0.17.20\", v\"0.18.0\", v\"0.18.10\", v\"0.18.13\",\n    v\"0.18.15\", v\"0.18.22\", v\"0.19.0\", v\"0.19.1\", v\"0.19.2\",\n    v\"0.19.3\", v\"0.19.4\", v\"0.19.5\", v\"0.19.6\"]\nconst KITCHEN_COLLECTORS = (\n    :benchmark, :chairmark, :alloc, :profile_alloc, :profile, :wall_profile)\n\n\"The same twelve workloads across tagged DataStructures releases and six collectors.\"\nfunction build_suite()\n    features = FeatureSpec[]\n    for kind in (\"heap\", \"vector\", \"counter\", \"buffer\"), n in (64, 2048, 32768),\n        collector in KITCHEN_COLLECTORS\n\n        workload = Symbol(kind, \"_\", n)\n        push!(features,\n            FeatureSpec(Symbol(workload, \"_\", collector);\n                workload, backend = collector,\n                entrypoint = joinpath(@__DIR__, \"workloads\", string(workload) * \".jl\"),\n                comparison_key = \"events/\$(kind)/\$(n)/seed42/v1\",\n                oracle = OracleSpec(),\n                state_policy = collector in (:profile, :wall_profile) ? :reuse : :fresh,\n                options = Dict(\n                    :samples => 30, :evals => 1, :seconds => 0.25, :threads => 1)))\n    end\n    package = PackageSuite(\n        \"DataStructures\"; worker_environment = joinpath(@__DIR__, \"workers\"),\n        versions = KITCHEN_VERSIONS, include_dev = false, features)\n    return SoftwareSuite(:event_lab, [package];\n        description = \"Deterministic event processing with DataStructures; Oxygen is measured separately\")\nend\n", "workloads/heap_32768.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"heap\", \"n\" => 32768))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/SplayTree_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"SplayTree\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Trie_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Trie\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Deque_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Deque\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/FenwickTree_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"FenwickTree\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/MultiDict_traverse.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"MultiDict\", \"traverse\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/Trie_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"Trie\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/DefaultOrderedDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"DefaultOrderedDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "containers/RobinDict_lookup.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"RobinDict\", \"lookup\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n", "workloads/counter_2048.jl" => "include(joinpath(@__DIR__, \"../src/PerfCheckerKitchenSink.jl\"))\nconst event_lifecycle = PerfCheckerKitchenSink.event_case(Dict(\n    \"kind\" => \"counter\", \"n\" => 2048))\nperf_setup() = event_lifecycle.prepare()\nperf_workload(state) = event_lifecycle.operation(state)\nperf_oracle(state, result) = event_lifecycle.verify(state, result)\n", "containers/DefaultDict_build.jl" => "include(joinpath(@__DIR__, \"../src/containers.jl\"))\nconst lifecycle = ContainerCases.container_case(\"DefaultDict\", \"build\"; n = 512)\nperf_setup() = lifecycle.prepare()\nperf_workload(state) = lifecycle.operation(state)\nperf_oracle(state, result) = lifecycle.verify(state, result)\n")
    for (relative,source) in runtime_sources
        destination=joinpath(notebook_root,relative)
        mkpath(dirname(destination))
        if isfile(destination)
            read(destination,String)==source || error("Notebook workload was edited: "*destination*". Preserve it and choose another notebook root.")
        else
            write(destination,source)
        end
    end
    (controller=Base.active_project(),core=pkgversion(PerfChecker),makie=pkgversion(PerfCheckerMakie),pluto_companion=pkgversion(PerfCheckerPluto),workers_started=false)
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000003
begin
    struct NotebookActionButton
        label::String
    end
    Base.get(::NotebookActionButton)=""
    function Base.show(io::IO,::MIME"text/html",button::NotebookActionButton)
        label=replace(button.label,'&'=>"&amp;",'<'=>"&lt;",'>'=>"&gt;")
        print(io,"<span><button type='button'>",label,"</button><script>const span=currentScript.parentElement;span.value='';span.firstElementChild.addEventListener('click',event=>{span.value=crypto.randomUUID();span.dispatchEvent(new CustomEvent('input'));event.stopPropagation()});</script></span>")
    end
    last_launch=Ref("");last_cancel=Ref("");last_save=Ref("")
    active_job=Ref{Any}(nothing);last_saved=Ref("")
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000004
md"""## Prepare a real suite
**Experiment** $( @bind campaign Select(["35 containers", "Event workloads"]))

The suite pins registered target releases. It stores fresh-state preparation and independent verification alongside each workload. The controller loads DataStructures 0.19.6 for suite preparation; measured target releases resolve in separate worker environments."""

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000005
@bind collector Select(["benchmark","chairmark"])

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000006
begin
    definition_module=Module(gensym(:DataStructuresNotebookSuite))
    Core.eval(definition_module, :(include(path)=Base.include($definition_module,path)))
    definition_path=joinpath(notebook_root,campaign=="35 containers" ? "containers-suite.jl" : "suite.jl")
    Base.include(definition_module,definition_path)
    experiment_suite=campaign=="35 containers" ? Base.invokelatest(getfield(definition_module,:build_container_suite);backends=(Symbol(collector),)) : Base.invokelatest(getfield(definition_module,:build_suite))
    full_plan=filter_suite_plan(plan_suite(experiment_suite;profile=:historical);backends=Symbol(collector))
    features=sort!(unique(string(run.feature.id) for run in full_plan.runs))
    targets=sort!(unique(run.target.version for run in full_plan.runs))
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000007
md"""**Workload** $(@bind feature Select(features))

**First release** $(@bind first_version Select(string.(targets);default=string(first(targets))))

**Last release** $(@bind last_version Select(string.(targets);default=string(last(targets))))"""

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000008
begin
    selected_plan=filter_suite_plan(full_plan;features=[feature],from_version=VersionNumber(first_version),to_version=VersionNumber(last_version))
    Markdown.parse("```text\n"*sprint(print_suite_plan,selected_plan)*"\n```")
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000009
begin
    first_run=first(selected_plan.runs)
    oracle_source=read(first_run.variant.entrypoint,String)
    Markdown.parse("### The selected lifecycle\nThe target worker loads this entry point. `perf_setup` prepares state; `perf_workload` performs the operation; `perf_oracle` verifies the answer. Inspect the embedded helper source in the notebook runtime for the complete independent oracle.\n\n```julia\n"*oracle_source*"\n```")
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000010
md"""**Samples** $(@bind samples NumberField(1:10000;default=30))

**Seconds per benchmark** $(@bind seconds NumberField(0.1:0.1:60;default=0.5))

Workers use **one Julia thread** and `evals=1`. Preparation and verification stay outside timing. A narrow release pair is a better starting selection than a complete campaign."""

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000011
@bind launch_click NotebookActionButton("Launch selected checks")

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000012
job=begin
    if launch_click isa AbstractString && !isempty(launch_click) && launch_click!=last_launch[]
        last_launch[]=launch_click
        active_job[]!==nothing && suite_job_status(active_job[]) ∉ (:complete,:failed,:cancelled) && error("A job is already running; refresh or cancel it first.")
        isempty(selected_plan.runs) && error("Choose a non-empty release range.")
        active_job[]=launch_suite(selected_plan;overrides=Dict{Symbol,Any}(:samples=>samples,:seconds=>seconds,:threads=>1,:evals=>1))
    end
    active_job[]
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000013
md"""$(@bind refresh_click CounterButton("Refresh status"))

$(@bind cancel_click NotebookActionButton("Cancel active job"))"""

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000014
begin
    if cancel_click isa AbstractString && !isempty(cancel_click) && cancel_click!=last_cancel[]
        last_cancel[]=cancel_click
        job===nothing || cancel!(job)
    end
    snapshot=(refresh_click;job===nothing ? Dict("state"=>"idle","completed"=>0,"total"=>0) : suite_job_progress(job))
    HTML("<p role='status'><strong>Status:</strong> "*get(snapshot,"state","idle")*" · "*string(get(snapshot,"completed",0))*" / "*string(get(snapshot,"total",0))*" checks completed</p>")
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000015
job_result=(snapshot;job===nothing || suite_job_status(job) ∉ (:complete,:failed) ? nothing : wait_suite(job;strict=false))

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000016
@bind save_click NotebookActionButton("Save completed reports")

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000017
begin
    if save_click isa AbstractString && !isempty(save_click) && save_click!=last_save[]
        last_save[]=save_click
        job_result===nothing && error("Refresh a completed job before saving.")
        reports_root=joinpath(notebook_root,"results");mkpath(reports_root)
        destination=mktempdir(reports_root;prefix="pluto-",cleanup=false)
        write_suite_reports(job_result,destination)
        last_saved[]=destination
    end
    isempty(last_saved[]) ? "No new measurement launched or saved." : "Saved reports: "*last_saved[]
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000018
begin
    fresh_bundle=job_result===nothing ? nothing : PerfChecker._suite_run_bundle(job_result)
    fresh_entries=fresh_bundle===nothing ? [] : filter(plot_catalog(fresh_bundle)) do entry
        model=performance_plot(fresh_bundle,entry["id"])
        observed=unique(string(row["version"]) for row in model.data if haskey(row,"version"))
        model.kind===:normalized_metrics && length(observed)>=2
    end
    single_target_values=fresh_bundle===nothing ? Any[] : [merge(Dict("workload"=>entry["title"]),row) for entry in plot_catalog(fresh_bundle) if entry["kind"]=="normalized_metrics" for model in (performance_plot(fresh_bundle,entry["id"]),) if length(unique(string(row["version"]) for row in model.data))==1 for row in model.data]
    fresh_status=job_result===nothing ? "No new result: the recorded views below are independent saved evidence." : "New suite correctness passed: "*string(suite_passed(job_result))
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000019
@bind fresh_view Select(isempty(fresh_entries) ? [""=>"No new multi-release result"] : [entry["id"]=>entry["title"] for entry in fresh_entries])

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000020
if !isempty(fresh_view) && fresh_bundle!==nothing
    notebook_plot(performance_plot(fresh_bundle,fresh_view))
elseif isempty(single_target_values)
    Markdown.parse(fresh_status)
else
    Markdown.parse(fresh_status*"\n\n| Workload | Target | Metric | Minimum |\n| --- | --- | --- | --- |\n"*join(["| "*row["workload"]*" | "*row["version"]*" | "*row["metric"]*" | "*string(row["value"])*" "*row["unit"]*" |" for row in single_target_values],"\n"))
end

# ╔═╡ d94ace53-1a4d-4c46-91c7-000000000021
